/**
 * npm's `version` lifecycle hook: stamps the release into the files npm does
 * not manage, then stages them so they land in npm's own release commit.
 *
 * Runs after npm has written the new version and before it stages
 * package.json, so the codename needs no second commit or amend.
 *
 * - package.json "codename", from CMU_CODENAME
 * - Makefile VERSION / PATCHLEVEL / SUBLEVEL / EXTRAVERSION
 * - resources/extension.zip, regenerated by the `preversion` build
 *   (build-info.json is regenerated too, but untracked: every build makes a
 *   new random id, so a committed one never matched a shipped app)
 */
const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");

const ROOT = path.resolve(__dirname, "..");
const PACKAGE_JSON_PATH = path.join(ROOT, "package.json");
const MAKEFILE_PATH = path.join(ROOT, "Makefile");
const BUILD_OUTPUTS = ["resources/extension.zip"];

/**
 * Rewrites the kernel-style version fields of a Makefile.
 * A prerelease suffix has no field of its own and is dropped.
 * @param {string} makefile - The Makefile content.
 * @param {string} version - The new semver version.
 * @param {string} codename - The release codename.
 * @returns {string} The updated Makefile content.
 * @throws {Error} When a version field is missing from the Makefile.
 */
function updateMakefileVersion(makefile, version, codename) {
  const [major, minor, patch] = version.split("-")[0].split(".");
  const fields = {
    VERSION: major,
    PATCHLEVEL: minor,
    SUBLEVEL: patch,
    EXTRAVERSION: codename,
  };

  return Object.entries(fields).reduce((content, [name, value]) => {
    const line = new RegExp(`^${name}\\s*=.*$`, "m");
    if (!line.test(content)) {
      throw new Error(`Makefile has no ${name} line`);
    }
    return content.replace(line, `${name} = ${value}`);
  }, makefile);
}

/**
 * Hook entry point.
 * @returns {void}
 */
function main() {
  const codename = process.env.CMU_CODENAME;
  if (!codename) {
    console.error("sync-release-files: CMU_CODENAME is not set");
    process.exit(1);
  }

  const pkg = JSON.parse(fs.readFileSync(PACKAGE_JSON_PATH, "utf8"));
  pkg.codename = codename;
  fs.writeFileSync(PACKAGE_JSON_PATH, JSON.stringify(pkg, null, 2) + "\n");

  const makefile = fs.readFileSync(MAKEFILE_PATH, "utf8");
  fs.writeFileSync(
    MAKEFILE_PATH,
    updateMakefileVersion(makefile, pkg.version, codename),
  );

  execFileSync("git", ["add", "Makefile", ...BUILD_OUTPUTS], {
    cwd: ROOT,
    stdio: "inherit",
  });
}

if (require.main === module) main();

module.exports = { updateMakefileVersion };
